def find_gaps(self, img, min_gap=35, threshold=3500) -> List[Tuple[int, int, int]]:
    """Find vertical white gaps"""
    h, w = img.shape[:2]
    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    _, binary = cv2.threshold(gray, 240, 255, cv2.THRESH_BINARY_INV)

    row_content = np.sum(binary, axis=1)
    gaps = []

    in_gap = False
    gap_start = 0

    for i, content in enumerate(row_content):
        if content < threshold:
            if not in_gap:
                in_gap = True
                gap_start = i
        else:
            if in_gap:
                gap_size = i - gap_start
                if gap_size >= min_gap:
                    gaps.append((gap_start, i, gap_size))
                in_gap = False

    return gaps

